WITH scored AS (SELECT id, temp_c, pressure, firmware, AVG(temp_c) OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS temp_c_avg_2, LAST_VALUE(temp_c) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_temp_c, CORR(temp_c, humidity) OVER (PARTITION BY device_code) AS corr_temp_c_humidity FROM device_readings) SELECT id, temp_c, pressure, temp_c_avg_2, corr_temp_c_humidity FROM scored ORDER BY temp_c_avg_2 DESC NULLS FIRST;
